    @{Group='convenience'; Section='officer_ui'; Key='unified'; Default=0; Requires=''; Inherit=''; Tab='편의성'; Retired=$true; Label='통합 인사·무장 검색·출진 전법 자동 선택'; Note='개발 중지로 제거된 기능입니다.'}
